create table if not exists social_entries (id bigserial primary key, author_name text not null, author_photo_url text, entry_type text not null check(entry_type in ('review','comment')), rating numeric(2,1) check(rating between 1 and 5), body text not null, source text not null default 'facebook', status text not null default 'published' check(status in ('draft','published','hidden')), featured boolean not null default false, published_at timestamptz, created_by_admin_id bigint references admins(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists social_entry_photos (id bigserial primary key, social_entry_id bigint not null references social_entries(id) on delete cascade, image_url text not null, sort_order integer not null default 0, alt_text text);
create table if not exists social_reactions (id bigserial primary key, social_entry_id bigint not null references social_entries(id) on delete cascade, reaction_type text not null check(reaction_type in ('like','love','haha','wow','sad','angry')), reaction_count integer not null default 0 check(reaction_count >= 0), unique(social_entry_id,reaction_type));
create index if not exists social_entries_public_idx on social_entries(status,published_at desc) where status='published';
insert into social_entries(author_name,entry_type,rating,body,status,featured,published_at) select 'Priya Mendes','review',5,'A beautiful and peaceful stay in Nuwara Eliya! The apartment was immaculate.','published',true,now()-interval '10 days' where not exists(select 1 from social_entries);
